WITH recent_web_events AS (SELECT * FROM web_events WHERE event_type = 'purchase' AND event_type IN ('page_view', 'search')), event_quarter_summary AS (SELECT QUARTER(event_time) AS event_quarter, COUNT(CASE WHEN page = '/cart' THEN 1 END) AS cart_count, COUNT(DISTINCT duration_sec) AS unique_pages FROM recent_web_events GROUP BY QUARTER(event_time)) SELECT * FROM event_quarter_summary ORDER BY unique_pages DESC
